# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İYONİK BAĞIN OLUŞUMU: ELEKTRON ALIŞVERİŞİ VE LEWİS GÖSTERİMİ (9.2.2)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">METAL + AMETAL → TUZ (NaCl ÖRNEĞİ)</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#1e3a8a">• ₁₁Na (2-8-1): 1 değerlik e⁻ verir → Na⁺ (Katyon)</text>\n  <text x="35" y="120" font-size="11" font-weight="bold" fill="#1e3a8a">• ₁₇Cl (2-8-7): 1 e⁻ alır → [ :Cl: ]⁻ (Anyon)</text>\n  <rect x="35" y="138" width="290" height="44" rx="8" fill="#ffffff" stroke="#93c5fd" stroke-width="1.5"/>\n  <text x="180" y="165" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Na·  +  ·Cl:  →  Na⁺ [:Cl:]⁻</text>\n  <text x="35" y="205" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Katyon: Köşeli parantezsiz, noktasız, üstte + yük.</text>\n  <text x="35" y="223" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Anyon: Köşeli parantez içinde 8 nokta (oktet), üstte - yük.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">FARKLI İYON YÜKLERİNDE LEWİS YAPISI</text>\n  <text x="378" y="98" font-size="11" font-weight="bold" fill="#14532d">1. Magnezyum Florür (MgF₂):</text>\n  <text x="378" y="118" font-size="10.5" fill="#166534">₁₂Mg (2-8-2) → 2 e⁻ verir | ₉F (2-7) → 1 e⁻ alır</text>\n  <text x="378" y="138" font-size="11.5" font-weight="bold" fill="#b91c1c">Lewis:  Mg²⁺  2 [:F:]⁻   (veya [:F:]⁻ Mg²⁺ [:F:]⁻)</text>\n  <text x="378" y="170" font-size="11" font-weight="bold" fill="#14532d">2. Kalsiyum Oksit (CaO):</text>\n  <text x="378" y="190" font-size="10.5" fill="#166534">₂₀Ca (2-8-8-2) → 2 e⁻ verir | ₈O (2-6) → 2 e⁻ alır</text>\n  <text x="378" y="212" font-size="11.5" font-weight="bold" fill="#b91c1c">Lewis:  Ca²⁺  [:O:]²⁻</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İYONİK KRİSTAL ÖRGÜ YAPISI VE BİRİM HÜCRE (NaCl KRİSTALİ)</text>\n  <rect x="20" y="45" width="310" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="175" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">3 BOYUTLU İYONİK KRİSTAL AĞI</text>\n  <circle cx="95" cy="115" r="14" fill="#ef4444"/><text x="95" y="119" text-anchor="middle" font-size="10" font-weight="bold" fill="#fff">Na⁺</text>\n  <circle cx="175" cy="115" r="20" fill="#22c55e"/><text x="175" y="119" text-anchor="middle" font-size="10" font-weight="bold" fill="#fff">Cl⁻</text>\n  <circle cx="255" cy="115" r="14" fill="#ef4444"/><text x="255" y="119" text-anchor="middle" font-size="10" font-weight="bold" fill="#fff">Na⁺</text>\n  <circle cx="95" cy="185" r="20" fill="#22c55e"/><text x="95" y="189" text-anchor="middle" font-size="10" font-weight="bold" fill="#fff">Cl⁻</text>\n  <circle cx="175" cy="185" r="14" fill="#ef4444"/><text x="175" y="189" text-anchor="middle" font-size="10" font-weight="bold" fill="#fff">Na⁺</text>\n  <circle cx="255" cy="185" r="20" fill="#22c55e"/><text x="255" y="189" text-anchor="middle" font-size="10" font-weight="bold" fill="#fff">Cl⁻</text>\n  <line x1="109" y1="115" x2="155" y2="115" stroke="#78350f" stroke-width="2"/>\n  <line x1="195" y1="115" x2="241" y2="115" stroke="#78350f" stroke-width="2"/>\n  <line x1="115" y1="185" x2="161" y2="185" stroke="#78350f" stroke-width="2"/>\n  <line x1="189" y1="185" x2="235" y2="185" stroke="#78350f" stroke-width="2"/>\n  <line x1="95" y1="129" x2="95" y2="165" stroke="#78350f" stroke-width="2"/>\n  <line x1="175" y1="135" x2="175" y2="171" stroke="#78350f" stroke-width="2"/>\n  <line x1="255" y1="129" x2="255" y2="165" stroke="#78350f" stroke-width="2"/>\n  <text x="175" y="225" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">Her Na⁺ etrafında 6 Cl⁻, her Cl⁻ etrafında 6 Na⁺!</text>\n  <rect x="350" y="45" width="330" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="515" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">NEDEN MOLEKÜL DEĞİL, BİRİM HÜCREDİR?</text>\n  <text x="368" y="96" font-size="10.5" font-weight="bold" fill="#581c87">• İyonik bileşikler bağımsız moleküllerden oluşmaz;</text>\n  <text x="368" y="114" font-size="10.5" fill="#6b21a8">  devasa 3 boyutlu kristal örgü yapısına sahiptir.</text>\n  <text x="368" y="140" font-size="10.5" font-weight="bold" fill="#581c87">• Tekrarlanan en küçük yapı taşına BİRİM HÜCRE denir.</text>\n  <text x="368" y="166" font-size="10.5" font-weight="bold" fill="#581c87">• NaCl formülü molekül formülü değil, iyonların</text>\n  <text x="368" y="184" font-size="10.5" fill="#6b21a8">  en sade birleşme oranını (1:1) gösteren</text>\n  <text x="368" y="202" font-size="10.5" font-weight="bold" fill="#b91c1c">  BİRİM HÜCRE (KABA) FORMÜLÜDÜR!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İYONİK BİLEŞİKLERİN ÖZELLİKLERİ VE BAĞ SAĞLAMLIĞI</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">FİZİKSEL VE KİMYASAL ÖZELLİKLER</text>\n  <text x="35" y="94" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Oda koşullarında tamamı KATI ve KRİSTAL hâldedir.</text>\n  <text x="35" y="118" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Erime ve kaynama noktaları oldukça yüksektir.</text>\n  <text x="35" y="142" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Sert ve kırılgandırlar; darbeyle tel/levha olmazlar.</text>\n  <text x="35" y="166" font-size="10.5" font-weight="bold" fill="#b91c1c">• KATI hâlde elektriği İLETMEZLER (iyonlar sabit).</text>\n  <text x="35" y="190" font-size="10.5" font-weight="bold" fill="#15803d">• SIVI (erimiş) hâlde ve SULU ÇÖZELTİDE serbest</text>\n  <text x="35" y="208" font-size="10.5" font-weight="bold" fill="#15803d">  iyon hareketiyle elektriği İLETİRLER (elektrolit).</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">İYONİK BAĞ KUVVETİ (F ∝ |q₁ · q₂| / r²)</text>\n  <text x="375" y="98" font-size="11" font-weight="bold" fill="#7f1d1d">1. İyon Yüklerinin Çarpımı (|q₁ · q₂|):</text>\n  <text x="375" y="116" font-size="10.5" fill="#991b1b">İyon yükleri büyüdükçe çekim kuvveti ve erime</text>\n  <text x="375" y="132" font-size="10.5" font-weight="bold" fill="#b91c1c">noktası ARTAR (Örn: MgO [2852 °C] &gt; NaCl [801 °C]).</text>\n  <text x="375" y="162" font-size="11" font-weight="bold" fill="#7f1d1d">2. İyon Yarıçapı / Bağ Uzunluğu (r):</text>\n  <text x="375" y="180" font-size="10.5" fill="#991b1b">İyon yarıçapı küçüldükçe çekim kuvveti ve erime</text>\n  <text x="375" y="196" font-size="10.5" font-weight="bold" fill="#b91c1c">noktası ARTAR (Örn: NaF &gt; NaCl &gt; NaBr &gt; NaI).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
